    if (this.activeOperation && !TERMINAL.has(this.activeOperation.state)) return { ok: false, reason: 'SERVICE_RECONCILIATION_REQUIRED' };
    if (String(this.getMode()) !== 'active') return { ok: false, reason: 'RUNTIME_NOT_ACTIVE' };
