      if (need && need.reason === 'LOGISTICS_RENDEZVOUS' && HOME_BUSY_PHASES.has(String(economy.phase || ''))) {
        stats.softRendezvousDeferrals += 1;
        return null;
      }
      if (need && need.reason !== 'LOGISTICS_RENDEZVOUS') stats.urgentPartyNeedsObserved += 1;
      return need;
