      nonServiceRendezvousBlocks: 0,
      inRangeRendezvousClears: 0,
      logisticsMovementAuthorityBlocks: 0,
      softRendezvousDeferrals: 0,
      urgentPartyNeedsObserved: 0,
      rangedEngagementRangeEvaluations: 0,
      rangedFirePositionMoves: 0,
