    this.merchantRecoveryResumeHpRatio = clamp(options.merchantRecoveryResumeHpRatio == null ? 0.72 : options.merchantRecoveryResumeHpRatio, this.merchantRecoveryTriggerHpRatio + 0.05, 0.95);
